console.log('✓ Negative number test passed');

// Test with larger numbers
assert.strictEqual(add(100, 200), 300, '100 + 200 should equal 300');
console.log('✓ Large number test passed');

// Test with zero
assert.strictEqual(add(0, 5), 5, '0 + 5 should equal 5');
assert.strictEqual(add(5, 0), 5, '5 + 0 should equal 5');
console.log('✓ Zero addition test passed');

// Test commutative property
assert.strictEqual(add(3, 7), add(7, 3), 'Addition should be commutative');
console.log('✓ Commutative property test passed');

console.log('All tests passed!');

